head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getInsertedXML]<br/>Row 의 상태가 '삽입' 인 Row 데이터를 XML 객체로 반환합니다.",
    "validation" : [
        "필터/정렬이 적용된 상태를 기준으로 Row 상태값이 'C' 인 Row 데이터가 반환됩니다.",
        "반환값으로 필터/정렬이 적용된 상태를 기준으로 Row 상태가 '삽입' 인 데이터를 XML 객체로 반환합니다.",
        "setColumnFilter() 메소드로 필터링 되지 않은 경우 전체 Row 데이터를 XML 객체로 반환합니다.",
        "반환된 객체의 xml 속성값으로 원본 DataList 모듈의 baseNode 속성값이 Root 노드의 태그명으로, 반복되는 데이터 노드의 태그엔 repeatNode 속성값이 적용됩니다.",
        "Root 노드의 id 속성은 원본 DataList 모듈의 ID 가 설정됩니다.",
        "데이터 노드는 index 속성으로 필터가 적용되지 않은 원본 DataList 모듈의 Row 인덱스값이 설정됩니다.",
        "데이터 노드의 하위 노드로 원본 DataList 모듈의 Column ID 와 Column 값이 반복됩니다.",
        "데이터 노드는 'rowStatus' 를 마지막 하위 태그로 Row 의 상태값 'C' 가 설정되며 'statusValue' 속성으로 상태코드값 2 가 설정됩니다.",        
        "원본 DataLIst 모듈이 rowNumData=true 인 경우 반환값의 마지막 Key 로 'rowNum' 이 추가되고 Row 의 순번(인덱스+1)값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList('rowNumData="true"');
    $c.gcm.createBasicLinkedDataList();

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = gdl_org.insertRow();
    gdl_org.setRowData(insertIndex,["A","insert2","insert3","insert4"],true);

    gdl_org.deleteRow(insertIndex);
};



scwin.btn_deleteRow_onclick = function (e) {
    gdl_org.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    gdl_org.setCellData(2, "cat2", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    gdl_org.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:"row", colIndex:"cat2", key:"A1", condition:"and"});
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("label", 1);
};



scwin.btn_getInsertedXML_onclick = function (e) {
    let rtn = target1.getInsertedXML();
    const serializer = new XMLSerializer();
    let xmlString = serializer.serializeToString(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.xml: " + xmlString);
};
